<?php $fails=0; function check($name,$ok){global $fails; echo ($ok?'PASS ':'FAIL ').$name."\n"; if(!$ok)$fails++;} $db=new PDO('sqlite::memory:'); $db->exec('CREATE TABLE customers(id INTEGER PRIMARY KEY,email TEXT,active INTEGER);CREATE TABLE tasks(id INTEGER PRIMARY KEY,customer_id INTEGER,title TEXT,status TEXT,note TEXT);INSERT INTO customers VALUES(1,"a",1),(2,"b",0);INSERT INTO tasks VALUES(1,1,"A","OPEN",NULL),(2,1,"B","DONE","done"),(3,2,"C","OPEN",NULL);'); require __DIR__.'/../app/Services/TaskService.php'; $s=new App\Services\TaskService($db); check('E1 open filter excludes DONE',count($s->listOpen(1))===1); check('E2 nullable note remains null', $s->listOpen(1)[0]['note']===null); try{$s->complete(3,2);check('I1 inactive customer forbidden',false);}catch(Throwable $e){check('I1 inactive customer forbidden',$e->getMessage()==='Forbidden');} try{$s->complete(1,99);check('I2 wrong customer rejected',false);}catch(Throwable $e){check('I2 wrong customer rejected',$e->getMessage()==='Forbidden');} exit($fails);
